{
  "a_sentences": [
    {
      "a_text": "La question litigieuse porte sur la rente d'invalidité de l'intimée postérieurement au 31 octobre 2020.",
      "b_propositions": ["P1"]
    },
    {
      "a_text": "Les bases légales applicables à l'incapacité de travail, à l'invalidité et à la rente d'invalidité sont correctement exposées par la juridiction cantonale.",
      "b_propositions": ["P2"]
    },
    {
      "a_text": "Le Tribunal fédéral rappelle les principes régissant la valeur probante des rapports médicaux, la procédure probatoire structurée pour les troubles psychiques et les conditions de rentes rétroactivement limitées ou échelonnées.",
      "b_propositions": ["P3"]
    },
    {
      "a_text": "Un renvoi pour instruction complémentaire ne cause pas un préjudice irréparable à l'assureur, mais peut seulement prolonger ou renchérir la procédure.",
      "b_propositions": ["P4"]
    },
    {
      "a_text": "La juridiction cantonale a retenu que l'intimée avait exercé un emploi à 50 % dès août 2020, ce qui a conduit à la conclusion d'une stabilisation de l'état de santé et à l'octroi d'une quart de rente dès novembre 2020.",
      "b_propositions": ["P5"]
    },
    {
      "a_text": "Le Tribunal fédéral considère que l'appréciation des preuves par la juridiction cantonale n'est pas arbitraire et qu'aucune amélioration de l'état de santé de l'intimée ne peut être établie avec une vraisemblance prépondérante.",
      "b_propositions": ["P6"]
    },
    {
      "a_text": "Le Tribunal fédéral rejette le recours de l'assureur en ce qui concerne le droit à la rente de l'intimée entre le 1er novembre 2020 et le 31 juillet 2021.",
      "b_propositions": ["P7"]
    },
    {
      "a_text": "Le Tribunal fédéral n'entre pas en matière sur le recours en tant qu'il porte sur la période du 1er août 2021 au 30 avril 2022, car il s'agit d'un renvoi pour instruction complémentaire constituant un arrêt incident.",
      "b_propositions": ["P8"]
    }
  ]
}
